function collectAcquireSettings(){const get=id=>$('#'+id)?.value??'';return{mode:selectedAcquireMode(),coordinates:get('acquireCoordinates'),pointHeading:get('pointHeading'),bboxWest:get('bboxWest'),bboxSouth:get('bboxSouth'),bboxEast:get('bboxEast'),bboxNorth:get('bboxNorth'),bboxSpacing:get('bboxSpacing'),bboxLimit:get('bboxLimit'),roadSpacing:get('roadSpacing'),roadPointLimit:get('roadPointLimit'),roadMethod:acquisition.roadMethod,roadBounds:acquisition.roadBounds,selectedRoadIds:[...acquisition.selectedRoadIds],regionProvince:get('regionProvince'),regionCity:get('regionCity'),regionCounty:get('regionCounty'),regionTown:get('regionTown')}}
