async function saveActiveProject(){if(!state.activeProjectId)return;if(projectSyncBusy){projectSyncAgain=true;return}projectSyncBusy=true;let imageUrlsChanged=false;try{const projectId=state.activeProjectId,itemsSnapshot=[...state.batchItems],acquisitionRecords=(acquisition?.items||[]).map(({thumbnail,url,...point})=>point),history=state.history.slice(0,50).map(({file,...item})=>({...item,time:item.time instanceof Date?item.time.toISOString():item.time}));await projectRequest(`/${encodeURIComponent(projectId)}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({acquisition:acquisitionRecords,settings:collectAcquireSettings(),items:itemsSnapshot.map(projectItemRecord),history})});for(const item of itemsSnapshot){if(!(item.file instanceof Blob)||!item.file.size||item.projectAsset)continue;await projectRequest(`/${encodeURIComponent(projectId)}/items/${encodeURIComponent(item.id)}/image`,{method:'PUT',headers:{'Content-Type':item.file.type||'application/octet-stream'},body:item.file});item.projectAsset=true;if(item.url?.startsWith('blob:'))URL.revokeObjectURL(item.url);item.file={name:item.file.name,size:item.file.size,type:item.file.type};item.url=projectImageUrl(projectId,item.id);imageUrlsChanged=true}if(imageUrlsChanged)renderBatch();const note=$('#batchFooterNote');if(note)note.textContent=`工程“${state.activeProjectName}”已保存 · 图片文件保存在电脑工程目录`;if(projectSyncAgain){projectSyncAgain=false;projectSyncBusy=false;return saveActiveProject()}}finally{projectSyncBusy=false}}
