function boxIoU(a,b){const x1=Math.max(a.xmin,b.xmin),y1=Math.max(a.ymin,b.ymin),x2=Math.min(a.xmax,b.xmax),y2=Math.min(a.ymax,b.ymax),intersection=Math.max(0,x2-x1)*Math.max(0,y2-y1),union=(a.xmax-a.xmin)*(a.ymax-a.ymin)+(b.xmax-b.xmin)*(b.ymax-b.ymin)-intersection;return union>0?intersection/union:0}
$('#runDetection').addEventListener('click',async()=>{if(state.busy)return;if(state.batchBusy){toast('批量任务处理中，完成后再运行单图检测');return}if(!state.image){toast('请先上传一张街景图片');input.click();return}state.modelId=state.modelId||$('#modelSelect').value;const btn=$('#runDetection');state.busy=true;setSingleControlsLocked(true);btn.disabled=true;btn.innerHTML='<span>◌</span> 加载模型…';try{setWorkflow(2);btn.innerHTML='<span>◌</span> 正在推理…';let ms;if(state.modelId==='custom:onnx'){const result=await detectCustomOnnx(state.imageUrl);state.predictions=result.predictions;ms=result.ms}else{const detector=await loadModel(),started=performance.now(),output=await detector(state.imageUrl,{threshold:0.01,percentage:true});ms=Math.round(performance.now()-started);state.predictions=convertPredictions(output)}state.hasDetection=true;state.currentHistoryId=null;state.selected=null;state.undoStack=[];state.redoStack=[];updateEditButtons();$('#thresholdLabel').textContent=Number($('#threshold').value).toFixed(2);$('.image-footer>div:nth-child(2) b').innerHTML=`${ms} <small>ms</small>`;drawBoxes();updateAnalytics();setWorkflow(3);addHistory();toast(`预标注完成：模型检测到 ${state.predictions.length} 个候选目标`)}catch(error){console.error(error);toast(`模型加载或推理失败：${error.message||'请检查网络连接后重试'}`)}finally{state.busy=false;setSingleControlsLocked(false);btn.disabled=false;btn.innerHTML='<span>✳</span> 运行检测 <kbd>↵</kbd>'}});
