function renderBatchPreview(){const panel=$('#batchResultViewer');if(!panel)return;const completed=state.batchItems.filter(item=>item.status==='done');if(!completed.length){panel.hidden=true;return}let index=completed.findIndex(item=>item.id===state.batchPreviewId);if(index<0){index=completed.length-1;state.batchPreviewId=completed[index].id}const item=completed[index],empty=$('#batchPreviewEmpty'),image=$('#batchPreviewImage');panel.hidden=false;$('#batchPreviewName').textContent=item.file.name;$('#batchPreviewMeta').textContent=`${countable(item.predictions).length} 个当前筛选目标 / ${item.predictions.length} 个候选目标 · ${item.ms||0} ms · ${item.model||'当前模型'} · ${item.reviewed?'已确认':'待确认'}`;$('#batchPreviewPosition').textContent=`${index+1} / ${completed.length}`;$('#batchPreviewPrev').disabled=completed.length<2;$('#batchPreviewNext').disabled=completed.length<2;empty.hidden=true;empty.textContent='图片载入中…';image.onload=()=>{empty.hidden=true};image.onerror=()=>{empty.textContent='图片文件暂不可显示';empty.hidden=false};image.alt=`${item.file.name} 检测结果`;image.src=item.url;const boxes=$('#batchPreviewBoxes');boxes.replaceChildren();countable(item.predictions).forEach((prediction,i)=>{const box=document.createElement('div');box.className='batch-preview-box';box.style.cssText=`left:${prediction.box.xmin}%;top:${prediction.box.ymin}%;width:${prediction.box.xmax-prediction.box.xmin}%;height:${prediction.box.ymax-prediction.box.ymin}%;border-color:${colors[i%colors.length]}`;const label=document.createElement('span');label.style.background=colors[i%colors.length];label.textContent=`${prediction.labelZh} ${prediction.manual?'人工':`${(prediction.score*100).toFixed(0)}%`}`;box.appendChild(label);boxes.appendChild(box)});if(image.complete){if(image.naturalWidth)empty.hidden=true;else{empty.textContent='图片文件暂不可显示';empty.hidden=false}}}
async function previewSelectedAcquisitionImages(){const selected=acquisition.items.filter(item=>item.selected);if(!selected.length)return;const pending=selected.filter(item=>!item.thumbnail);if(!pending.length){toast('所选采样点已有街景预览');return}if(pending.length>25){toast('一次最多预览 25 张，请分批勾选采样点');return}if(!await checkAcquisitionService()){toast('请先运行 acquisition_service/start_acquisition_service.command');return}acquisition.previewBusy=true;renderAcquireResults();let success=0,failed=0;try{for(let i=0;i<pending.length;i++){const point=pending[i];setAcquireProgress(i,pending.length,'正在获取街景预览 '+(i+1)+' / '+pending.length);try{const result=await acquisitionRequest('/api/preview',{latitude:point.latitude,longitude:point.longitude,heading:point.heading,point_id:point.point_id,road_id:point.road_id||''});point.thumbnail='data:image/jpeg;base64,'+result.image_base64;point.previewError='';if(result.pano_id)point.pano_id=result.pano_id;success++}catch(error){point.previewError=error.message||'无可用街景';failed++}renderAcquireResults()}setAcquireProgress(pending.length,pending.length,'预览完成 · '+success+' 张可用'+(failed?' · '+failed+' 张无可用街景':''));if(success)toast('已显示 '+success+' 张采样点街景缩略图')}finally{acquisition.previewBusy=false;renderAcquireResults()}}
