function updateBatchEditActions(){const bar=$('#batchReviewBar');if(!bar)return;const item=state.batchItems.find(x=>x.id===state.currentBatchId);bar.hidden=!item; if(item){$('#batchReviewTitle').textContent=`正在复核：${item.file.name}`;$('#batchReviewHint').textContent='标注修改会自动保存回当前批量任务'}}
