$('#batchPreviewPrev')?.addEventListener('click',()=>stepBatchPreview(-1));$('#batchPreviewNext')?.addEventListener('click',()=>stepBatchPreview(1));$('#batchReviewReturn')?.addEventListener('click',()=>{const current=state.batchItems.find(x=>x.id===state.currentBatchId);if(current){current.predictions=clonePredictions();persistWorkspaceSoon()}state.currentBatchId=null;updateBatchEditActions();renderBatch();showPage('page-batch')});$('#batchReviewNext')?.addEventListener('click',()=>finishBatchReview(true));
