$('#runBatch')?.addEventListener('click',async()=>{const queue=state.batchItems.filter(x=>x.status==='queued'||x.status==='error');if(!queue.length){toast('请先添加待检测图片');return}const button=$('#runBatch'),runModel=state.modelId||$('#modelSelect').value;state.modelId=runModel;setBatchControlsLocked(true);button.disabled=true;try{await saveActiveProject();await loadModel();for(let i=0;i<queue.length;i++){const item=queue[i];item.status='running';item.error='';renderBatch();$('#batchProgressText').textContent=`正在处理 ${i+1} / ${queue.length}：${item.file.name}`;try{let result;if(state.modelId==='custom:onnx')result=await detectCustomOnnx(item.url);else{const started=performance.now(),output=await state.detector(item.url,{threshold:0.01,percentage:true});result={predictions:convertPredictions(output),ms:Math.round(performance.now()-started)}}item.predictions=result.predictions;item.ms=result.ms;item.model=runModel;item.confidenceThreshold=Number($('#threshold').value);item.selectedClasses=$$('.class-option input:checked').map(input=>input.dataset.class);item.status='done';item.reviewed=false;state.batchPreviewId=item.id;state.history.unshift({id:crypto.randomUUID?.()||`${Date.now()}-${Math.random()}`,batchId:item.id,file:item.file,predictions:item.predictions.map(p=>({...p,box:{...p.box}})),model:item.model,time:new Date(),ms:String(item.ms),hasDetection:true});state.history=state.history.slice(0,30)}catch(err){item.status='error';item.error=err.message||'推理失败'}$('#batchProgressValue').textContent=`${Math.round((i+1)/queue.length*100)}%`;$('#batchProgressBar').style.width=`${Math.round((i+1)/queue.length*100)}%`;renderBatch()}renderHistory();$('#batchProgressText').textContent='批量处理完成';toast(`批量任务完成：${queue.filter(x=>x.status==='done').length} 张成功`)}catch(err){toast(`模型加载失败：${err.message}`)}finally{setBatchControlsLocked(false);button.disabled=false;renderBatch()}});
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function renderDetectionImage(item){const img=await loadImageElement(item.url),canvas=document.createElement('canvas');canvas.width=img.naturalWidth;canvas.height=img.naturalHeight;const ctx=canvas.getContext('2d');ctx.drawImage(img,0,0);const scale=canvas.width/100;ctx.lineWidth=Math.max(2,canvas.width/600);ctx.font=`${Math.max(13,canvas.width/70)}px sans-serif`;countable(item.predictions).forEach((p,i)=>{const x=p.box.xmin*scale,y=p.box.ymin*canvas.height/100,w=(p.box.xmax-p.box.xmin)*scale,h=(p.box.ymax-p.box.ymin)*canvas.height/100,color=colors[i%colors.length];ctx.strokeStyle=color;ctx.strokeRect(x,y,w,h);const text=`${p.labelZh} ${p.manual?'人工':`${(p.score*100).toFixed(0)}%`}`,th=Math.max(20,canvas.width/35);ctx.fillStyle=color;ctx.fillRect(x,Math.max(0,y-th),Math.min(ctx.measureText(text).width+12,canvas.width-x),th);ctx.fillStyle='#fff';ctx.fillText(text,x+5,Math.max(th*.72,y-5))});return new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.9))}
function stableNameHash(value){let hash=2166136261;for(const char of String(value)){hash^=char.charCodeAt(0);hash=Math.imul(hash,16777619)}return hash>>>0}
function makeTrainingSplit(items,ratio){const grouped=new Map();items.forEach(item=>{const key=item.sourceMetadata?.road_id?`road:${item.sourceMetadata.road_id}`:`image:${item.id}`;if(!grouped.has(key))grouped.set(key,[]);grouped.get(key).push(item)});const groups=[...grouped.entries()].sort((a,b)=>stableNameHash(a[0])-stableNameHash(b[0]));const target=Math.max(1,Math.min(items.length-1,Math.round(items.length*ratio))),split=new Map();let valCount=0;if(groups.length>1){for(let i=0;i<groups.length-1&&valCount<target;i++){for(const item of groups[i][1])split.set(item.id,'val');valCount+=groups[i][1].length}}if(!valCount){const ordered=[...items].sort((a,b)=>stableNameHash(a.file.name+a.id)-stableNameHash(b.file.name+b.id));for(let i=0;i<target;i++)split.set(ordered[i].id,'val')}items.forEach(item=>{if(!split.has(item.id))split.set(item.id,'train')});return{split,byRoad:groups.length>1&&items.every(item=>Boolean(item.sourceMetadata?.road_id))}}
async function exportBatchZip(training=false,download=true){const items=state.batchItems.filter(x=>x.status==='done'&&(!training||x.reviewed));if(!items.length){toast(training?'请先完成并复核图片，至少复核 2 张后再导出训练集':'请先完成批量检测');return}if(training&&items.length<2){toast('训练集至少需要 2 张已复核图片');return}const {default:JSZip}=await import('https://cdn.jsdelivr.net/npm/jszip@3.10.1/+esm'),zip=new JSZip();if(training&&!items.some(item=>countable(item.predictions).length)){toast('已复核图片中没有当前筛选的目标框');return}if(!training){const data=items.map(x=>({image:x.file.name,source:x.sourceMetadata||null,model:x.model||'Xenova/yolos-tiny',visible_confidence_threshold:Number($('#threshold').value),selected_classes:$$('.class-option input:checked').map(input=>input.dataset.class),inference_ms:x.ms,reviewed:Boolean(x.reviewed),annotations:countable(x.predictions).map(p=>({category:p.label,category_zh:p.labelZh,confidence:p.manual?null:p.score,manual:!!p.manual,bbox_percent:[p.box.xmin,p.box.ymin,p.box.xmax,p.box.ymax]}))}));zip.file('batch_results.json',JSON.stringify(data,null,2));for(let i=0;i<items.length;i++){const item=items[i],prefix=String(i+1).padStart(5,'0'),safe=item.file.name.replace(/[^\w.-]+/g,'_');zip.file(`images/${prefix}_${safe}`,await getBatchFile(item));const rendered=await renderDetectionImage(item);if(rendered)zip.file(`visualizations/${prefix}_${safe.replace(/\.[^.]+$/,'')}.jpg`,rendered)}}else{const classes=[...new Set(items.flatMap(x=>countable(x.predictions).map(p=>p.label)))].sort(),splitInfo=makeTrainingSplit(items,Number($('#trainValSplit')?.value||.2));for(let i=0;i<items.length;i++){const item=items[i],prefix=splitInfo.split.get(item.id)||'train',stem=`${String(i+1).padStart(5,'0')}_${item.file.name.replace(/[^\w.-]+/g,'_')}`;zip.file(`images/${prefix}/${stem}`,await getBatchFile(item));const txt=countable(item.predictions).map(p=>{const cid=classes.indexOf(p.label),cx=(p.box.xmin+p.box.xmax)/200,cy=(p.box.ymin+p.box.ymax)/200,w=(p.box.xmax-p.box.xmin)/100,h=(p.box.ymax-p.box.ymin)/100;return `${cid} ${cx.toFixed(6)} ${cy.toFixed(6)} ${w.toFixed(6)} ${h.toFixed(6)}`}).join('\n');zip.file(`labels/${prefix}/${stem.replace(/\.[^.]+$/,'')}.txt`,txt)}zip.file('data.yaml',`path: .\ntrain: images/train\nval: images/val\nnames:\n${classes.map((x,i)=>`  ${i}: ${JSON.stringify(x)}`).join('\n')}\n`);zip.file('README.txt','YOLO 数据集包。仅导出已复核图片，标签遵守当前置信度与类别筛选。已采集街景按 road_id 分组划分；缺少多条道路分组时按图片划分，请在训练前检查相邻样本泄漏。\n');zip.file('split_info.txt',`训练图片：${items.filter(x=>splitInfo.split.get(x.id)==='train').length}\n验证图片：${items.filter(x=>splitInfo.split.get(x.id)==='val').length}\n按道路分组：${splitInfo.byRoad?'是':'否，采用图片级划分'}\n`);const sourced=items.filter(x=>x.sourceMetadata);if(sourced.length)zip.file('ATTRIBUTION.txt',sourced.map(x=>`${x.file.name} | ${x.sourceMetadata.attribution} | ${x.sourceMetadata.image_url} | ${x.sourceMetadata.license} | 坐标 ${x.sourceMetadata.latitude}, ${x.sourceMetadata.longitude}`).join('\n')+'\n')}const blob=await zip.generateAsync({type:'blob'});if(!download)return blob;downloadBlob(blob,training?'street_dataset_yolo.zip':'street_batch_results.zip');toast(training?'YOLO 数据集包已导出':'批量结果包已导出');return blob}
$('#downloadBatchJson')?.addEventListener('click',()=>exportBatchZip(false));async function downloadTrainingArchive(){try{await exportBatchZip(true)}catch(error){toast(`数据包导出失败：${error.message}`)}}$('#downloadTrainingZip')?.addEventListener('click',downloadTrainingArchive);$('#downloadTrainingZip2')?.addEventListener('click',downloadTrainingArchive);$('#downloadTrainYaml')?.addEventListener('click',()=>{const body=`# YOLO 训练配置草案\nmodel: ${$('#trainBaseModel').value}\ndata: data.yaml\nepochs: ${$('#trainEpochs').value}\nimgsz: ${$('#trainImageSize').value}\nbatch: ${$('#trainBatchSize').value}\ndevice: ${$('#trainDevice').value}\nworkers: ${$('#trainWorkers').value}\npatience: ${$('#trainPatience').value}\n`;downloadBlob(new Blob([body],{type:'text/yaml'}),'training_config.yaml')});
$('#importCustomModel')?.addEventListener('click',()=>{const file=$('#customOnnxFile').files[0],classes=$('#customClassNames').value.split(',').map(x=>x.trim()).filter(Boolean);if(!file||!file.name.toLowerCase().endsWith('.onnx')){toast('请选择 .onnx 模型文件');return}if(!classes.length){toast('请填写模型类别名称');return}state.customOnnxFile=file;state.customClassNames=classes;state.customSession=null;let opt=$('#modelSelect').querySelector('option[value="custom:onnx"]');if(!opt){opt=new Option('自定义 YOLOv8 ONNX · 本地','custom:onnx');$('#modelSelect').append(opt)}$('#modelSelect').value='custom:onnx';$('#modelSelect').dispatchEvent(new Event('change'));$('#customModelStatus').textContent=`已导入 ${file.name} · ${classes.length} 个类别 · 首次推理时载入`;$('#removeCustomModel').hidden=false;toast('自定义模型已加入模型列表')});$('#removeCustomModel')?.addEventListener('click',()=>{state.customOnnxFile=null;state.customSession=null;state.customClassNames=[];$('#modelSelect').querySelector('option[value="custom:onnx"]')?.remove();$('#modelSelect').value='Xenova/yolos-tiny';$('#modelSelect').dispatchEvent(new Event('change'));$('#customModelStatus').textContent='尚未导入自定义模型 · 支持 YOLOv8 输出张量 [1, 4+类别数, 候选框数]';$('#removeCustomModel').hidden=true});
$('#openProjectButton')?.addEventListener('click',async()=>{try{await openProject($('#openProjectSelect').value)}catch(error){toast('打开工程失败：'+error.message)}});$('#createProjectButton')?.addEventListener('click',createProject);$('#exportProjectButton')?.addEventListener('click',()=>{if(!state.activeProjectId)return;const link=document.createElement('a');link.href=PROJECT_API+'/'+encodeURIComponent(state.activeProjectId)+'/export';link.download='';link.click()});$('#importProjectButton')?.addEventListener('click',()=>$('#projectArchiveInput').click());$('#projectArchiveInput')?.addEventListener('change',event=>{const file=event.target.files?.[0];if(file)importProjectArchive(file);event.target.value=''});$('#welcomeForm')?.addEventListener('submit',async event=>{event.preventDefault();const mode=$('[name=appMode]:checked')?.value||'simple';if(mode==='project'){await showProjectSetupModal();return}await enterAppMode('simple',$('#welcomeName').value)});$$('[name=appMode]').forEach(input=>input.addEventListener('change',()=>{if(input.checked&&input.value==='project'){if(!$('#welcomeName').value.trim()){toast('请先填写你的称呼');$('#welcomeName').focus();$('[name=appMode][value=simple]').checked=true;return}showProjectSetupModal()}}));$('#switchModeButton')?.addEventListener('click',openModeChooser);$('#singleGuideProjectMode')?.addEventListener('click',()=>{try{$('#welcomeName').value=activeUserName||localStorage.getItem('streetVisionUserName')||''}catch{};$$('[name=appMode]').forEach(input=>input.checked=input.value==='project');showProjectSetupModal()});$('#projectSetupForm')?.addEventListener('submit',createProjectFromSetup);$('#closeProjectSetup')?.addEventListener('click',closeProjectSetupModal);$('#projectSetupModal')?.addEventListener('click',event=>{if(event.target.classList.contains('project-setup-backdrop'))closeProjectSetupModal()});$('#projectSetupName')?.addEventListener('input',()=>{if(!$('#projectStoragePath').dataset.custom)suggestProjectPath()});$('#projectStoragePath')?.addEventListener('input',event=>{event.target.dataset.custom='1'});$('#chooseProjectDirectory')?.addEventListener('click',async()=>{const button=$('#chooseProjectDirectory');button.disabled=true;try{const result=await projectRequest('/choose-directory',{method:'POST'}),path=$('#projectStoragePath');path.dataset.basePath=result.path;path.dataset.custom='';await suggestProjectPath()}catch(error){if(!/已取消/.test(error.message)){const missingRoute=/Not Found|404/.test(error.message);$('#projectSetupMessage').textContent=missingRoute?'本机街景服务仍在运行旧版本。请关闭并重新启动 acquisition_service/start_acquisition_service.command，再刷新本页。':error.message}}finally{button.disabled=false}});$('#openExistingFromSetup')?.addEventListener('click',async()=>{const id=$('#existingProjectSelect').value;if(!id)return;closeProjectSetupModal();await enterAppMode('project',activeUserName||$('#welcomeName').value.trim()||'用户',id)});updateWelcomeDefaults();
$('#exportAnnotations').addEventListener('click',()=>{if(!state.file||!state.hasDetection){toast('请先完成一次检测');return}const data={image:{name:state.file.name,width:state.image.naturalWidth,height:state.image.naturalHeight},model:state.modelId||'Xenova/yolos-tiny',threshold:Number($('#threshold').value),selected_classes:$$('.class-option input:checked').map(input=>input.dataset.class),annotations:countable().map(p=>({category:p.label,category_zh:p.labelZh,confidence:p.manual?null:Number(p.score.toFixed(6)),manual:Boolean(p.manual),bbox_xyxy:[p.box.xmin/100*state.image.naturalWidth,p.box.ymin/100*state.image.naturalHeight,p.box.xmax/100*state.image.naturalWidth,p.box.ymax/100*state.image.naturalHeight].map(n=>Math.round(n*100)/100)}))};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=state.file.name.replace(/\.[^.]+$/,'')+'_annotations.json';a.click();URL.revokeObjectURL(url);setWorkflow(4);toast('标注 JSON 已导出')});

const TRAINING_API='http://127.0.0.1:8766';
function setTrainingServiceBadge(ok,message){const badge=$('#trainingServiceBadge');badge.textContent=message;badge.className='service-badge '+(ok?'online':'offline')}
function friendlyDevice(device){return ({cuda:'NVIDIA CUDA',mps:'Apple MPS',cpu:'CPU'})[device]||device||'等待连接'}
async function checkTrainingService(){setTrainingServiceBadge(false,'正在连接…');try{const response=await fetch(`${TRAINING_API}/api/health`,{cache:'no-store'});if(!response.ok)throw new Error(`服务返回 ${response.status}`);const info=await response.json();if(!info.ok)throw new Error(info.ultralytics_error||'训练环境未完整安装');setTrainingServiceBadge(true,'服务已连接');$('#trainingDeviceInfo').textContent=friendlyDevice(info.device);$('#trainingPythonInfo').textContent=info.python||'—';$('#trainingUltralyticsInfo').textContent=info.ultralytics||'—';await refreshTrainingHistory();toast(`训练服务已连接 · 推荐设备 ${friendlyDevice(info.device)}`);return info}catch(error){setTrainingServiceBadge(false,'服务未连接');$('#trainingDeviceInfo').textContent='未连接';$('#trainingUltralyticsInfo').textContent='待安装';toast('未连接训练服务。请先运行 training_service/start_training_service.command');return null}}
function renderTrainingTask(task){if(task.task_id)state.lastTrainingTaskId=task.task_id;if(Array.isArray(task.class_names)){state.lastTrainingClasses=task.class_names;state.lastTrainingImageSize=Number(task.imgsz)||640}$('#downloadTrainedOnnx').disabled=true;const total=Number(task.total_epochs)||0,epoch=Number(task.epoch)||0,percent=total?Math.min(100,Math.round(epoch/total*100)):0;$('#trainingTaskMessage').textContent=task.message||'等待任务状态';$('#trainingEpochLabel').textContent=`${epoch} / ${total} 轮`;$('#trainingProgressBar').style.width=`${percent}%`;const metrics=task.metrics||{};$('#trainingMetrics').textContent=Object.keys(metrics).length?Object.entries(metrics).map(([key,value])=>`${key}: ${Number(value).toFixed(4)}`).join('　·　'):'训练指标将在每轮验证后显示。';$('#trainingLog').textContent=task.log_tail||task.traceback||'日志已连接，等待训练输出…';$('#trainingOutputPath').textContent=task.output_dir?`结果目录：${task.output_dir}`:'权重保存位置：任务完成后显示';const terminal=['completed','error','cancelled'].includes(task.status);$('#stopTraining').disabled=terminal;$('#launchTraining').disabled=!terminal&&Boolean(state.trainingTaskId);if(task.status==='completed'){state.trainingTaskId=null;$('#launchTraining').disabled=Number($('#trainImages').textContent)<2||Number($('#trainBoxes').textContent)<1;$('#downloadTrainedWeights').disabled=!task.weights_path;$('#downloadTrainedOnnx').disabled=!task.weights_path||!state.lastTrainingClasses.length;$('#trainingOutputPath').textContent=task.weights_path?`最佳权重：${task.weights_path}`:'任务完成；未找到 best.pt';if(state.trainingPoll){clearInterval(state.trainingPoll);state.trainingPoll=null}setTrainingServiceBadge(true,'训练已完成')}else if(task.status==='error'||task.status==='cancelled'){state.trainingTaskId=null;$('#launchTraining').disabled=Number($('#trainImages').textContent)<2||Number($('#trainBoxes').textContent)<1;if(state.trainingPoll){clearInterval(state.trainingPoll);state.trainingPoll=null}setTrainingServiceBadge(task.status==='error'?'offline':'online',task.status==='error'?'任务异常':'任务已停止')}else if(task.status==='running'||task.status==='queued'){state.trainingTaskId=task.task_id;$('#launchTraining').disabled=true;$('#stopTraining').disabled=false}}
async function pollTrainingTask(){if(!state.trainingTaskId)return;try{const response=await fetch(`${TRAINING_API}/api/training/tasks/${state.trainingTaskId}`,{cache:'no-store'});if(!response.ok)throw new Error(`状态读取失败 (${response.status})`);renderTrainingTask(await response.json())}catch(error){$('#trainingTaskMessage').textContent=`状态连接中断：${error.message}`}}
function beginTrainingPolling(taskId){state.trainingTaskId=taskId;$('#launchTraining').disabled=true;$('#stopTraining').disabled=false;$('#trainingTaskMessage').textContent='任务已创建，等待训练环境启动';if(state.trainingPoll)clearInterval(state.trainingPoll);pollTrainingTask();state.trainingPoll=setInterval(pollTrainingTask,2500)}

async function refreshTrainingHistory(){const container=$('#trainingTaskHistory');if(!container)return;try{const response=await fetch(`${TRAINING_API}/api/training/tasks`,{cache:'no-store'});if(!response.ok)throw new Error('读取任务列表失败');const tasks=await response.json();container.innerHTML='';if(!tasks.length){container.textContent='暂无本机训练任务记录。';return}const statusNames={queued:'排队中',running:'训练中',completed:'已完成',error:'异常',cancelled:'已停止'};tasks.forEach(task=>{const row=document.createElement('div');row.className='training-task-row';row.innerHTML='<div class="training-task-meta"><b></b><span></span><small></small></div><div class="training-task-buttons"><button class="small-button task-view">查看</button><button class="small-button task-weight" disabled>下载权重</button></div>';row.querySelector('.training-task-meta b').textContent=`${task.model||'YOLO'} · ${statusNames[task.status]||task.status}`;row.querySelector('.training-task-meta span').textContent=task.message||`${task.epoch||0} / ${task.total_epochs||0} 轮`;row.querySelector('.training-task-meta small').textContent=new Date(task.created_at*1000).toLocaleString('zh-CN');row.querySelector('.task-view').addEventListener('click',async()=>{state.lastTrainingTaskId=task.task_id;const detail=await fetch(`${TRAINING_API}/api/training/tasks/${task.task_id}`,{cache:'no-store'}).then(r=>r.json());renderTrainingTask(detail);if(['queued','running'].includes(detail.status))beginTrainingPolling(task.task_id)});const weight=row.querySelector('.task-weight');weight.disabled=task.status!=='completed'||!task.weights_path;weight.addEventListener('click',()=>{window.location.href=`${TRAINING_API}/api/training/tasks/${task.task_id}/weights`});container.appendChild(row)})}catch(error){container.textContent=`无法读取任务记录：${error.message}`}}
$('#refreshTrainingHistory')?.addEventListener('click',refreshTrainingHistory);
$('#checkTrainingService')?.addEventListener('click',checkTrainingService);
$('#launchTraining')?.addEventListener('click',async()=>{if(Number($('#trainImages').textContent)<2||Number($('#trainBoxes').textContent)<1){toast('训练需要至少 2 张已复核图片，并包含目标框');return}if(!confirm('即将把当前批量图片与标注发送到本机 Python 服务，并启动真实训练。首次训练会下载预训练权重并占用 CPU/GPU 与内存。现在开始吗？'))return;const button=$('#launchTraining');button.disabled=true;button.textContent='正在准备数据…';try{const health=await checkTrainingService();if(!health)throw new Error('本机训练服务不可用');const archive=await exportBatchZip(true,false);if(!archive)throw new Error('无法生成训练数据包');const form=new FormData();form.append('dataset',new File([archive],'street_dataset_yolo.zip',{type:'application/zip'}));form.append('model',$('#trainBaseModel').value);form.append('epochs',$('#trainEpochs').value);form.append('imgsz',$('#trainImageSize').value);form.append('batch',$('#trainBatchSize').value);form.append('device',$('#trainDevice').value);form.append('workers',$('#trainWorkers').value);form.append('patience',$('#trainPatience').value);button.textContent='提交训练任务…';const response=await fetch(`${TRAINING_API}/api/training/start`,{method:'POST',body:form});const result=await response.json();if(!response.ok)throw new Error(result.detail||`提交失败 (${response.status})`);renderTrainingTask({status:'queued',task_id:result.task_id,epoch:0,total_epochs:Number($('#trainEpochs').value),message:'任务已提交，正在准备训练环境'});beginTrainingPolling(result.task_id);setTrainingServiceBadge(true,'训练进行中');toast('训练任务已提交；本机开始实际训练')}catch(error){button.disabled=Number($('#trainImages').textContent)<2;button.textContent='▶ 开始真实训练';toast(`无法启动训练：${error.message}`)}finally{button.textContent='▶ 开始真实训练'}});
$('#stopTraining')?.addEventListener('click',async()=>{if(!state.trainingTaskId)return;if(!confirm('确定停止当前训练任务？已保存的中间检查点会保留。'))return;try{const response=await fetch(`${TRAINING_API}/api/training/tasks/${state.trainingTaskId}/cancel`,{method:'POST'});const result=await response.json();if(!response.ok)throw new Error(result.detail||'停止失败');renderTrainingTask({status:'cancelled',task_id:state.trainingTaskId,message:'训练已停止；已有中间结果保留'});toast('训练任务已停止')}catch(error){toast(`停止任务失败：${error.message}`)}});
$('#downloadTrainedWeights')?.addEventListener('click',()=>{if(!state.lastTrainingTaskId){toast('当前会话没有已完成的训练任务');return}window.location.href=`${TRAINING_API}/api/training/tasks/${state.lastTrainingTaskId}/weights`});
$('#downloadTrainedOnnx')?.addEventListener('click',async()=>{if(!state.lastTrainingTaskId||!state.lastTrainingClasses.length){toast('训练任务中没有可用的类别配置');return}const button=$('#downloadTrainedOnnx');button.disabled=true;button.textContent='↻ 正在转换…';try{const response=await fetch(`${TRAINING_API}/api/training/tasks/${state.lastTrainingTaskId}/onnx`,{method:'POST'});if(!response.ok){const problem=await response.json().catch(()=>({}));throw new Error(problem.detail||`转换失败 (${response.status})`)}const blob=await response.blob(),file=new File([blob],`street-scene-${state.lastTrainingTaskId.slice(0,8)}.onnx`,{type:'application/octet-stream'});state.customOnnxFile=file;state.customClassNames=[...state.lastTrainingClasses];state.customSession=null;$('#customClassNames').value=state.customClassNames.join(',');$('#customImageSize').value=state.lastTrainingImageSize;let option=$('#modelSelect').querySelector('option[value="custom:onnx"]');if(!option){option=new Option('训练模型 · 本地 ONNX','custom:onnx');$('#modelSelect').append(option)}$('#customModelStatus').textContent=`已载入训练模型 ${file.name} · ${state.customClassNames.length} 个类别 · ${state.lastTrainingImageSize}px`;$('#removeCustomModel').hidden=false;$('#modelSelect').value='custom:onnx';$('#modelSelect').dispatchEvent(new Event('change'));showPage('page-workbench');toast('训练模型已转换并载入，可直接运行检测')}catch(error){toast(`模型转换失败：${error.message}`)}finally{button.disabled=false;button.textContent='↻ 转为浏览器模型'}});
const acquisition={items:[],controller:null,map:null,drawnArea:null,pointPreviewMap:null,pointPreviewLayers:null,bboxPreviewMap:null,bboxPreviewLayers:null,roadMap:null,roadLayers:new Map(),selectedRoadIds:new Set(),roadBounds:null,roadMethod:'select',roadRouteLayer:null,roadStart:null,roadEnd:null,roadMarkers:[]};
const ACQUISITION_API='http://127.0.0.1:8767';
function acquireStatus(text,online=false){const el=$('#acquisitionServiceStatus');if(el){el.textContent=text;el.style.color=online?'#28765a':'#a55050'}}
function setAcquireProgress(done,total,label){const pct=total?Math.round(done/total*100):0;$('#acquireProgressText').textContent=label;$('#acquireProgressValue').textContent=pct+'%';$('#acquireProgressBar').style.width=pct+'%'}
function validCoordinate(lat,lon){return Number.isFinite(lat)&&Number.isFinite(lon)&&Math.abs(lat)<=74&&Math.abs(lon)<=180}
function renderAcquireResults(){const list=$('#acquireResultList');if(!list)return;$('#acquireResultCount').textContent=acquisition.items.length+' 个采样点';const selectedItems=acquisition.items.filter(x=>x.selected),hasSelected=selectedItems.length>0;$('#addStreetImages').disabled=!hasSelected;$('#addStreetImages').hidden=['chat','road'].includes(selectedAcquireMode())&&!hasSelected;const previewButton=$('#previewAcquireImages');if(previewButton){previewButton.disabled=!hasSelected||acquisition.previewBusy;previewButton.textContent=acquisition.previewBusy?'正在获取预览…':'预览所选街景'}if(!acquisition.items.length){list.innerHTML='<div class="ranked-empty">生成道路采样点后，可勾选要采集的位置。</div>';persistWorkspaceSoon();return}list.innerHTML='';acquisition.items.forEach((item,index)=>{const row=document.createElement('label');row.className='acquire-result-row';const check=document.createElement('input');check.type='checkbox';check.checked=item.selected;check.addEventListener('change',()=>{item.selected=check.checked;renderAcquireResults()});const thumb=document.createElement('span');thumb.className='acquire-point-thumb';if(item.thumbnail){const image=document.createElement('img');image.src=item.thumbnail;image.alt='采样点街景预览';thumb.appendChild(image)}else{thumb.textContent=item.previewError?'预览失败':'待预览'}const meta=document.createElement('span');meta.innerHTML='<b></b><small></small>';meta.querySelector('b').textContent=(index+1)+'. '+item.latitude.toFixed(6)+', '+item.longitude.toFixed(6);meta.querySelector('small').textContent=(item.road_name||'坐标点')+' · '+item.heading.toFixed(1)+'° · '+(item.point_id||'')+(item.previewError?' · '+item.previewError:'')+(item.error?' · 失败：'+item.error:'');row.append(check,thumb,meta);list.appendChild(row)});persistWorkspaceSoon()}
async function acquisitionRequest(path,body,signal){const response=await fetch(ACQUISITION_API+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,signal});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.detail||'本机采集服务返回 '+response.status);return data}
async function checkAcquisitionService(){acquireStatus('正在连接…');try{const result=await acquisitionRequest('/api/health');acquireStatus(result.ok?(result.ai_proxy_configured?'已连接 · AI 中转已配置':'已连接 · 本地范围识别'):'服务未就绪',Boolean(result.ok));return Boolean(result.ok)}catch(error){acquireStatus('未连接');return false}}
$('#checkAcquisitionService')?.addEventListener('click',async()=>{const ok=await checkAcquisitionService();toast(ok?'本机免 Key 采集服务已连接':'请先运行 acquisition_service/start_acquisition_service.command')});
function selectedAcquireMode(){return $('input[name="acquireMode"]:checked')?.value||'road'}
function syncAcquireMode(){const mode=selectedAcquireMode();const modeHints={road:'按省、市、区县和街道定位，再选择道路生成采样点。',point:'粘贴纬度、经度，可选填写方向角；每行一个采样点。',bbox:'输入西、南、东、北边界和间距，按矩形范围生成点位。',map:'在地图上框选范围，再设置间距生成采样点。',chat:'输入城市、区县或地标，选择地图匹配结果后生成采样点。'};const select=$('#acquireModeSelect');if(select)select.value=mode;const hint=$('#acquireModeHint');if(hint)hint.textContent=modeHints[mode]||'';$('#acquireRoadFields').hidden=mode!=='road';$('#acquirePointFields').hidden=mode!=='point';$('#acquireBboxFields').hidden=mode!=='bbox';$('#acquireMapFields').hidden=mode!=='map';$('#acquireChatFields').hidden=mode!=='chat';$('#queryStreetImages').hidden=['chat','road'].includes(mode);$('#cancelStreetQuery').hidden=['chat','road'].includes(mode)&&!acquisition.controller;$('#addStreetImages').hidden=['chat','road'].includes(mode)&&!acquisition.items.some(x=>x.selected);if(mode==='map')ensureAcquireMap();if(mode==='road')ensureAcquireRoadMap();if(mode==='point'||mode==='bbox'){updateCoordinatePreview(mode);setTimeout(()=>acquisition[mode==='point'?'pointPreviewMap':'bboxPreviewMap']?.invalidateSize(),80)}$('#queryStreetImages').textContent=mode==='point'?'⌖ 准备坐标点':'⌖ 生成道路采样点'}
$('#acquireModeSelect')?.addEventListener('change',()=>{const radio=$$('[name="acquireMode"]').find(input=>input.value===$('#acquireModeSelect').value);if(radio){radio.checked=true;radio.dispatchEvent(new Event('change'))}});
$$('input[name="acquireMode"]').forEach(input=>input.addEventListener('change',syncAcquireMode));
syncAcquireMode();
function setAcquireBounds(bounds){$('#bboxWest').value=bounds.west.toFixed(6);$('#bboxSouth').value=bounds.south.toFixed(6);$('#bboxEast').value=bounds.east.toFixed(6);$('#bboxNorth').value=bounds.north.toFixed(6)}
function ensureCoordinatePreview(mode){const mapKey=mode==='point'?'pointPreviewMap':'bboxPreviewMap',layersKey=mode==='point'?'pointPreviewLayers':'bboxPreviewLayers',elementId=mode==='point'?'pointMapPreview':'bboxMapPreview';if(acquisition[mapKey])return acquisition[mapKey];const message=$('#'+(mode==='point'?'pointMapMessage':'bboxMapMessage'));if(!window.L){if(message)message.textContent='地图组件尚未加载；请联网后刷新页面。';return null}const map=L.map(elementId,{zoomControl:false,scrollWheelZoom:false}).setView([32.03,118.82],11);acquisition[mapKey]=map;acquisition[layersKey]=L.layerGroup().addTo(map);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>'}).addTo(map);return map}
function updateCoordinatePreview(mode){const map=ensureCoordinatePreview(mode);if(!map)return;const layers=acquisition[mode==='point'?'pointPreviewLayers':'bboxPreviewLayers'],message=$('#'+(mode==='point'?'pointMapMessage':'bboxMapMessage'));layers.clearLayers();if(mode==='point'){const rows=$('#acquireCoordinates').value.split(/\n+/).map(line=>line.trim()).filter(Boolean),points=[];rows.forEach((line,index)=>{const parts=line.split(/[，,\s]+/).filter(Boolean).map(Number);if((parts.length===2||parts.length===3)&&validCoordinate(parts[0],parts[1]))points.push({lat:parts[0],lon:parts[1],index:index+1})});if(!points.length){message.textContent='填写有效坐标后，地图会自动定位并显示采样点。';return}const markers=points.map(point=>L.circleMarker([point.lat,point.lon],{radius:7,color:'#fff',weight:2,fillColor:'#2584b8',fillOpacity:.95}).bindTooltip('点位 '+point.index,{direction:'top'}).addTo(layers));if(points.length===1)map.setView([points[0].lat,points[0].lon],16);else map.fitBounds(L.latLngBounds(points.map(point=>[point.lat,point.lon])).pad(.18),{maxZoom:16});message.textContent='地图已显示 '+points.length+' 个有效坐标点。';return}const west=$('#bboxWest').value.trim()===''?NaN:Number($('#bboxWest').value),south=$('#bboxSouth').value.trim()===''?NaN:Number($('#bboxSouth').value),east=$('#bboxEast').value.trim()===''?NaN:Number($('#bboxEast').value),north=$('#bboxNorth').value.trim()===''?NaN:Number($('#bboxNorth').value);if(![west,south,east,north].every(Number.isFinite)){message.textContent='填写完整的西、南、东、北边界后，地图会显示大致范围。';return}if(!(west<east&&south<north)||west< -180||east>180||south< -74||north>74){message.textContent='坐标范围暂不可预览，请检查西小于东、南小于北，且经纬度有效。';return}const bounds=[[south,west],[north,east]];L.rectangle(bounds,{color:'#2584b8',weight:2,fillColor:'#55a9d7',fillOpacity:.18}).addTo(layers);map.fitBounds(bounds,{maxZoom:16,padding:[18,18]});message.textContent='地图已标出输入范围，可拖动或缩放查看周边。'}
$('#acquireCoordinates')?.addEventListener('input',()=>{if(selectedAcquireMode()==='point')updateCoordinatePreview('point')});['bboxWest','bboxSouth','bboxEast','bboxNorth'].forEach(id=>$('#'+id)?.addEventListener('input',()=>{if(selectedAcquireMode()==='bbox')updateCoordinatePreview('bbox')}));
function ensureAcquireMap(){if(acquisition.map)return;if(!window.L){$('#acquireMapMessage').textContent='地图组件加载失败。请联网后刷新页面，或使用经纬度范围输入。';return}const map=L.map('acquireMap').setView([32.03,118.82],11);acquisition.map=map;L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>'}).addTo(map);const layers=new L.FeatureGroup().addTo(map);const drawControl=new L.Control.Draw({position:'topright',draw:{polyline:false,polygon:false,circle:false,marker:false,circlemarker:false,rectangle:{shapeOptions:{color:'#2584b8',weight:2,fillOpacity:.12}}},edit:{featureGroup:layers,edit:false,remove:false}});map.addControl(drawControl);map.on(L.Draw.Event.CREATED,event=>{layers.clearLayers();layers.addLayer(event.layer);acquisition.drawnArea=event.layer.getBounds();const b=acquisition.drawnArea;setAcquireBounds({west:b.getWest(),south:b.getSouth(),east:b.getEast(),north:b.getNorth()});$('#acquireMapMessage').textContent='范围已选好：西 '+b.getWest().toFixed(4)+'，南 '+b.getSouth().toFixed(4)+'，东 '+b.getEast().toFixed(4)+'，北 '+b.getNorth().toFixed(4)+'。点击“生成道路采样点”继续。';acquireStatus('地图范围已选',true)});setTimeout(()=>map.invalidateSize(),80)}
function pointToSegmentDistance(point,a,b){const dx=b.x-a.x,dy=b.y-a.y,length=dx*dx+dy*dy;if(!length)return Math.hypot(point.x-a.x,point.y-a.y);const t=Math.max(0,Math.min(1,((point.x-a.x)*dx+(point.y-a.y)*dy)/length));return Math.hypot(point.x-(a.x+t*dx),point.y-(a.y+t*dy))}
function toggleRoadSelection(id,layer){if(acquisition.selectedRoadIds.has(id)){acquisition.selectedRoadIds.delete(id);layer.setStyle({color:'#3986b7',weight:7,opacity:.86})}else{acquisition.selectedRoadIds.add(id);layer.setStyle({color:'#2c9a72',weight:12,opacity:1})}updateRoadSelectionStatus('已选 '+acquisition.selectedRoadIds.size+' 条路段。点击其他道路可继续多选，或点击已选道路取消。')}
function selectRoadAtMapClick(event){const map=acquisition.roadMap,point=map.latLngToLayerPoint(event.latlng);let nearest=null,nearestDistance=18;for(const [id,layer] of acquisition.roadLayers){const coords=layer.getLatLngs(),lines=Array.isArray(coords[0])?coords:[coords];for(const line of lines){for(let i=1;i<line.length;i++){const a=map.latLngToLayerPoint(line[i-1]),b=map.latLngToLayerPoint(line[i]),distance=pointToSegmentDistance(point,a,b);if(distance<nearestDistance){nearest={id,layer};nearestDistance=distance}}}}if(nearest){toggleRoadSelection(nearest.id,nearest.layer);return}updateRoadSelectionStatus('地图已收到点击，但附近没有道路；请点蓝色线条，或继续放大后重新加载道路。')}
function ensureAcquireRoadMap(){if(acquisition.roadMap)return;if(!window.L){setTimeout(()=>{if(window.L)ensureAcquireRoadMap();else $('#roadSelectionStatus').textContent='地图组件尚未加载，请联网刷新页面后再选择路段。'},500);return}const map=L.map('acquireRoadMap',{preferCanvas:true}).setView([32.03,118.82],14);acquisition.roadMap=map;L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>'}).addTo(map);map.on('click',event=>{if(selectedAcquireMode()!=='road')return;if(acquisition.roadMethod==='route'){handleRoadRouteClick(event.latlng);return}if(acquisition.roadMethod==='select'&&acquisition.roadLayers.size)selectRoadAtMapClick(event)});setTimeout(()=>map.invalidateSize(),120)}
function currentRoadBounds(){const b=acquisition.roadMap.getBounds();return{west:b.getWest(),south:b.getSouth(),east:b.getEast(),north:b.getNorth(),spacing_m:Number($('#roadSpacing').value)||100}}
function clearRoadRoute(){acquisition.roadRouteLayer?.remove();acquisition.roadRouteLayer=null;acquisition.roadMarkers.forEach(marker=>marker.remove());acquisition.roadMarkers=[]}
function clearRoadLayers(){acquisition.roadLayers.forEach(layer=>layer.remove());acquisition.roadLayers.clear();clearRoadRoute()}
function updateRoadSelectionStatus(message){$('#roadSelectionStatus').textContent=message;$('#generateRoadSamples').disabled=acquisition.roadMethod!=='select'||!acquisition.selectedRoadIds.size}
function setRoadMethod(method){acquisition.roadMethod=method;$('#roadSelectMethod').classList.toggle('selected',method==='select');$('#roadRouteMethod').classList.toggle('selected',method==='route');$('#loadRoadsButton').hidden=method==='route';$('#generateRoadSamples').hidden=method==='route';$('#clearRoadSelection').textContent=method==='route'?'重新选起终点':'清空选择';acquisition.roadStart=null;acquisition.roadEnd=null;acquisition.selectedRoadIds.clear();acquisition.items=[];renderAcquireResults();clearRoadRoute();acquisition.roadLayers.forEach(layer=>layer.setStyle({color:'#3986b7',weight:7,opacity:.72}));$('#generateRoadSamples').disabled=true;if(method==='select')updateRoadSelectionStatus('① 定位并放大到目标街区 ② 加载道路 ③ 悬停高亮后逐条点击，可多选 ④ 生成采样点。');else updateRoadSelectionStatus('依次点击地图上的道路起点和终点；系统会沿道路网络匹配路线并直接生成采样点。')}
async function loadRoadNetwork(){if(!acquisition.roadMap)ensureAcquireRoadMap();if(!acquisition.roadMap)return;try{if(!await checkAcquisitionService())throw new Error('本机采集服务未连接；请先启动采集服务');const bounds=currentRoadBounds();acquisition.roadBounds=bounds;$('#loadRoadsButton').disabled=true;updateRoadSelectionStatus('正在加载当前地图道路…');const result=await acquisitionRequest('/api/roads/preview',bounds);acquisition.roadLayers.forEach(layer=>layer.remove());acquisition.roadLayers.clear();clearRoadRoute();acquisition.selectedRoadIds.clear();acquisition.items=[];renderAcquireResults();const roadRenderer=L.canvas({padding:.5,tolerance:12});(result.roads||[]).forEach(road=>{const layer=L.polyline(road.geometry,{renderer:roadRenderer,interactive:true,color:'#3986b7',weight:7,opacity:.86});layer.bindTooltip((road.road_name||'未命名道路')+' · 点击选择',{sticky:true});layer.on('mouseover',()=>{acquisition.roadMap.getContainer().style.cursor='pointer';if(!acquisition.selectedRoadIds.has(road.road_id))layer.setStyle({color:'#f0a446',weight:12,opacity:1})});layer.on('mouseout',()=>{acquisition.roadMap.getContainer().style.cursor='';if(!acquisition.selectedRoadIds.has(road.road_id))layer.setStyle({color:'#3986b7',weight:7,opacity:.86})});layer.addTo(acquisition.roadMap);acquisition.roadLayers.set(road.road_id,layer)});if(!result.roads?.length)throw new Error('当前地图没有找到道路；请平移或放大后重试');updateRoadSelectionStatus('已从'+(result.source==='local-shapefile'?'本地全国道路数据':'在线道路数据')+'加载 '+result.roads.length+' 条路段。悬停高亮后点击，可多选。')}catch(error){updateRoadSelectionStatus(error.message)}finally{$('#loadRoadsButton').disabled=false}}
function limitSamplePoints(points,inputId){const raw=$('#'+inputId).value.trim();if(!raw)return points.slice(0,5000);const limit=Math.min(5000,Math.max(1,Math.floor(Number(raw)||1))),count=Math.min(limit,points.length);return count===points.length?points:count===1?[points[Math.floor((points.length-1)/2)]]:Array.from({length:count},(_,i)=>points[Math.round(i*(points.length-1)/(count-1))])}
function chooseRoadSamples(points){if(!points.length)throw new Error('所选路段没有生成采样点');const chosen=limitSamplePoints(points,'roadPointLimit');acquisition.items=chosen.map(point=>({...point,selected:true,thumbnail:null,previewError:''}));renderAcquireResults();const capped=chosen.length<points.length?'（已按上限抽取 '+chosen.length+' 点）':'';setAcquireProgress(1,1,'已准备 '+acquisition.items.length+' 个采样点'+capped)}
async function generateSelectedRoadSamples(){if(!acquisition.selectedRoadIds.size){updateRoadSelectionStatus('请先点击选择至少一条蓝色路段');return}if(!acquisition.roadBounds){updateRoadSelectionStatus('请先加载当前地图道路，再选择路段');return}try{updateRoadSelectionStatus('正在为所选路段生成采样点…');const result=await acquisitionRequest('/api/roads/sample',{...acquisition.roadBounds,spacing_m:Number($('#roadSpacing').value)||100,road_ids:[...acquisition.selectedRoadIds]});chooseRoadSamples(result.points||[]);updateRoadSelectionStatus('已生成 '+acquisition.items.length+' 个待采样点，可在右侧取消不需要的位置。')}catch(error){updateRoadSelectionStatus(error.message)}}
async function handleRoadRouteClick(latlng){if(acquisition.roadEnd){clearRoadRoute();acquisition.roadStart=null;acquisition.roadEnd=null;acquisition.selectedRoadIds.clear();acquisition.items=[];renderAcquireResults();updateRoadSelectionStatus('已清除上次路线。请重新点击起点。')}if(!acquisition.roadStart){acquisition.roadStart={lat:latlng.lat,lon:latlng.lng};const marker=L.marker(latlng,{title:'起点'}).addTo(acquisition.roadMap).bindTooltip('起点').openTooltip();acquisition.roadMarkers.push(marker);updateRoadSelectionStatus('起点已标记。请点击终点。');return}acquisition.roadEnd={lat:latlng.lat,lon:latlng.lng};const marker=L.marker(latlng,{title:'终点'}).addTo(acquisition.roadMap).bindTooltip('终点').openTooltip();acquisition.roadMarkers.push(marker);updateRoadSelectionStatus('正在沿道路查找起终点之间的路线…');try{const result=await acquisitionRequest('/api/roads/route',{start_lat:acquisition.roadStart.lat,start_lon:acquisition.roadStart.lon,end_lat:acquisition.roadEnd.lat,end_lon:acquisition.roadEnd.lon,spacing_m:Number($('#roadSpacing').value)||100});acquisition.roadRouteLayer=L.polyline(result.geometry,{color:'#e28b36',weight:8,opacity:.95}).addTo(acquisition.roadMap);acquisition.selectedRoadIds=new Set(result.road_ids||[]);chooseRoadSamples(result.points||[]);$('#generateRoadSamples').disabled=true;updateRoadSelectionStatus('路线约 '+result.distance_m+' 米，匹配 '+result.road_count+' 个道路片段，已生成 '+acquisition.items.length+' 个采样点。可在右侧取消不需要的位置。')}catch(error){updateRoadSelectionStatus(error.message);acquisition.roadEnd=null}}
$('#roadSelectMethod')?.addEventListener('click',()=>setRoadMethod('select'));
$('#roadRouteMethod')?.addEventListener('click',()=>setRoadMethod('route'));
$('#loadRoadsButton')?.addEventListener('click',loadRoadNetwork);
$('#clearRoadSelection')?.addEventListener('click',()=>{acquisition.selectedRoadIds.clear();acquisition.items=[];acquisition.roadStart=null;acquisition.roadEnd=null;if(acquisition.roadMethod==='route')clearRoadRoute();else clearRoadLayers();renderAcquireResults();updateRoadSelectionStatus(acquisition.roadMethod==='route'?'已清除路线，请重新点击起点和终点。':'选择已清空，请重新加载道路后继续。')});
$('#generateRoadSamples')?.addEventListener('click',generateSelectedRoadSamples);
const regionChildCache=new Map();
function resetRegionSelect(id,placeholder){const select=$('#'+id);select.replaceChildren(new Option(placeholder,''));select.disabled=true;}
function fillRegionSelect(id,items,placeholder){const select=$('#'+id);select.replaceChildren(new Option(placeholder,''));(items||[]).forEach(item=>{if(!item?.code||!item?.name)return;select.add(new Option(item.name,String(item.code)))});select.disabled=!items?.length;}
async function loadRegionProvinces(){const status=$('#regionSelectStatus');status.textContent='正在加载省份列表…';$('#roadLocateButton').disabled=true;try{const result=await acquisitionRequest('/api/regions/provinces');fillRegionSelect('regionProvince',result.items,'请选择省份');if(!result.items?.length)throw new Error('没有可用的省份数据');status.textContent='请选择省、市、区县和街道/乡镇；可以停在任一级定位。';}catch(error){resetRegionSelect('regionProvince','省份列表加载失败');status.textContent=error.message+' 可点击“重试加载”再次尝试。';}updateRegionLocateButton()}
async function loadRegionChildren(parentCode,targetId,prompt){if(!parentCode){resetRegionSelect(targetId,prompt);return}const select=$('#'+targetId),status=$('#regionSelectStatus');select.replaceChildren(new Option('正在加载…',''));select.disabled=true;try{let result=regionChildCache.get(parentCode);if(!result){result=await acquisitionRequest('/api/regions/children/'+encodeURIComponent(parentCode));regionChildCache.set(parentCode,result)}fillRegionSelect(targetId,result.items,prompt);const label=$('label[for="'+targetId+'"]');if(label){const type=result.childrenTypeName||'',tier=type.includes('乡')||type.includes('街')?'街道 / 乡镇':type.includes('县')||type.includes('区')?'区县':type.includes('级')&&type.includes('地')||type.includes('市')||type.includes('盟')||type.includes('州')?'市 / 地区':prompt.replace('请选择','');label.firstChild.textContent=tier;select.options[0].textContent='请选择'+tier}if(!result.items?.length)status.textContent='该级行政区暂无下级列表，可直接定位当前已选区域。';else status.textContent='已加载 '+result.items.length+' 个下级行政区。'}catch(error){resetRegionSelect(targetId,'下级列表加载失败');status.textContent=error.message+'；可以选择当前级别定位，或稍后重试。'}updateRegionLocateButton()}
function selectedRegionText(){return ['regionProvince','regionCity','regionCounty','regionTown'].map(id=>{const select=$('#'+id);return select.selectedOptions[0]?.textContent||''}).filter(Boolean).join(' ')}
function updateRegionLocateButton(){$('#roadLocateButton').disabled=!$('#regionProvince').value}
$('#regionProvince')?.addEventListener('change',event=>{resetRegionSelect('regionCity','正在加载市/地区…');resetRegionSelect('regionCounty','先选择市/地区');resetRegionSelect('regionTown','先选择区县');loadRegionChildren(event.target.value,'regionCity','请选择市/地区');updateRegionLocateButton()});
$('#regionCity')?.addEventListener('change',event=>{resetRegionSelect('regionCounty','正在加载区县…');resetRegionSelect('regionTown','先选择区县');loadRegionChildren(event.target.value,'regionCounty','请选择区县');updateRegionLocateButton()});
$('#regionCounty')?.addEventListener('change',event=>{resetRegionSelect('regionTown','正在加载街道/乡镇…');loadRegionChildren(event.target.value,'regionTown','请选择街道/乡镇');updateRegionLocateButton()});
$('#regionTown')?.addEventListener('change',updateRegionLocateButton);
$('#reloadRegionList')?.addEventListener('click',loadRegionProvinces);
function fitRoadMapToPlace(place,holder){if(!acquisition.roadMap)ensureAcquireRoadMap();if(!acquisition.roadMap)return;acquisition.roadMap.fitBounds([[place.south,place.west],[place.north,place.east]],{maxZoom:15});holder.hidden=true;acquisition.roadBounds=null;acquisition.items=[];clearRoadLayers();acquisition.selectedRoadIds.clear();renderAcquireResults();updateRoadSelectionStatus('已定位到所选行政区。请放大到目标街区，再点击“加载当前地图道路”。');setTimeout(()=>acquisition.roadMap.invalidateSize(),80)}
$('#roadLocateButton')?.addEventListener('click',async()=>{const selected=selectedRegionText();if(!selected)return;const button=$('#roadLocateButton'),holder=$('#roadPlaceChoices');button.disabled=true;$('#regionSelectStatus').textContent='正在搜索“'+selected+'”的地图范围…';try{const result=await acquisitionRequest('/api/place/search',{text:selected+'附近'}),places=result.places||[];holder.replaceChildren();holder.hidden=!places.length;if(!places.length)throw new Error('没有匹配到所选区域，请调整行政区级别后再定位。');places.forEach(place=>{const choice=document.createElement('button');choice.type='button';choice.className='acquire-place-choice';choice.textContent=place.place_name;choice.addEventListener('click',()=>fitRoadMapToPlace(place,holder));holder.appendChild(choice)});$('#regionSelectStatus').textContent='请选择地图匹配结果以确认范围。'}catch(error){$('#regionSelectStatus').textContent=error.message}finally{updateRegionLocateButton()}});
async function sampleSelectedArea(bounds){const {west,south,east,north}=bounds;if(![west,south,east,north].every(Number.isFinite)||!(west<east&&south<north)||west< -180||east>180||south< -74||north>74)throw new Error('采集范围坐标无效：请确认西经度小于东经度、南纬度小于北纬度，并检查经纬度是否填写正确。');const heightKm=(north-south)*111.2,widthKm=(east-west)*111.2*Math.max(.1,Math.cos((south+north)*Math.PI/360));if(heightKm>20||widthKm>20||heightKm*widthKm>400)throw new Error('采集范围过大：单次最多 20 km × 20 km、面积不超过 400 km²，请缩小范围后重试。');if(!await checkAcquisitionService())throw new Error('本机采集服务未连接；请先启动 acquisition_service');const req={west,south,east,north,spacing_m:Number($('#bboxSpacing').value)||100},sampled=await acquisitionRequest('/api/roads/sample',req),points=sampled.points||[];if(!points.length)throw new Error('范围内没有取得道路采样点');const chosen=limitSamplePoints(points,'bboxLimit');acquisition.items=chosen.map(x=>({...x,selected:true,thumbnail:null,previewError:''}));renderAcquireResults();acquireStatus('OSM 已生成 '+points.length+' 点',true);setAcquireProgress(1,1,'已准备 '+acquisition.items.length+' 个采样点'+(chosen.length<points.length?'（已按上限抽取）':''));return acquisition.items.length}
$('#queryStreetImages')?.addEventListener('click',async()=>{const mode=selectedAcquireMode();if(mode==='road'){if(acquisition.roadMethod==='select')await generateSelectedRoadSamples();else toast('请在地图上选择道路起点和终点');return}if(mode==='chat'){toast('请先查询并确认地点');return}acquisition.items=[];renderAcquireResults();try{if(mode==='point'){const defaultHeading=Number($('#pointHeading').value)||0,lines=$('#acquireCoordinates').value.split(/\n+/).map(line=>line.trim()).filter(Boolean);if(!lines.length)throw new Error('请至少填写一个坐标');if(lines.length>25)throw new Error('坐标点每次最多 25 个');acquisition.items=lines.map((line,i)=>{const parts=line.split(/[，,\s]+/).filter(Boolean).map(Number);if((parts.length!==2&&parts.length!==3)||!validCoordinate(parts[0],parts[1]))throw new Error('第 '+(i+1)+' 行坐标无效，请按“纬度, 经度[,方向角]”填写');const heading=parts[2]??defaultHeading;if(!Number.isFinite(heading)||heading<0||heading>=360)throw new Error('第 '+(i+1)+' 行方向角需在 0 到 359.9 度之间');return{latitude:parts[0],longitude:parts[1],heading,point_id:'coord_'+String(i+1).padStart(3,'0'),road_id:'',road_name:'手动坐标',selected:true}});renderAcquireResults();setAcquireProgress(1,1,'已准备 '+acquisition.items.length+' 个坐标点');toast('坐标点已准备：'+acquisition.items.length+' 个');return}const bounds={west:$('#bboxWest').value.trim()===''?NaN:Number($('#bboxWest').value),south:$('#bboxSouth').value.trim()===''?NaN:Number($('#bboxSouth').value),east:$('#bboxEast').value.trim()===''?NaN:Number($('#bboxEast').value),north:$('#bboxNorth').value.trim()===''?NaN:Number($('#bboxNorth').value)};if(![bounds.west,bounds.south,bounds.east,bounds.north].every(Number.isFinite))throw new Error(mode==='map'?'请先在地图上框选一个范围':'请填写完整的经纬度范围');await sampleSelectedArea(bounds)}catch(error){setAcquireProgress(0,1,error.message);toast('无法生成采样点：'+error.message)}});
$('#cancelStreetQuery')?.addEventListener('click',()=>acquisition.controller?.abort());
function addAcquireChatMessage(text,role='assistant'){const messages=$('#acquireChatMessages'),bubble=document.createElement('div');bubble.className=role==='user'?'acquire-chat-user':'acquire-chat-assistant';bubble.textContent=text;messages.appendChild(bubble);messages.scrollTop=messages.scrollHeight;return bubble}
function showPlaceChoices(places,query){const holder=$('#acquirePlaceChoices');holder.hidden=false;holder.innerHTML='';if(!places.length){holder.hidden=true;return}places.forEach((place,index)=>{const button=document.createElement('button');button.type='button';button.className='acquire-place-choice';button.innerHTML='<b></b><small></small>';button.querySelector('b').textContent=(index+1)+'. '+place.place_name;button.querySelector('small').textContent='地名检索结果 · 点击确认范围';button.addEventListener('click',async()=>{holder.querySelectorAll('.acquire-place-choice').forEach(x=>x.classList.remove('selected'));button.classList.add('selected');setAcquireBounds(place);if(acquisition.map){acquisition.map.fitBounds([[place.south,place.west],[place.north,place.east]],{maxZoom:16});setTimeout(()=>acquisition.map.invalidateSize(),60)}try{const count=await sampleSelectedArea(place);addAcquireChatMessage('已按“'+place.place_name+'”定位并生成 '+count+' 个道路采样点。你可以在右侧勾选要采集的位置。');toast('范围已确认，采样点已生成')}catch(error){addAcquireChatMessage('已找到“'+place.place_name+'”，但暂时无法生成采样点：'+error.message+'。可以缩小范围后重试，或手动填写经纬度。')}});holder.appendChild(button)})}
$('#acquireChatForm')?.addEventListener('submit',async event=>{event.preventDefault();const input=$('#acquireChatInput'),text=input.value.trim();if(!text)return;addAcquireChatMessage(text,'user');input.value='';const waiting=addAcquireChatMessage('正在识别地点并查询地图…');$('#acquireChatForm button').disabled=true;try{if(!await checkAcquisitionService())throw new Error('本机采集服务未连接；请先启动 acquisition_service');const result=await acquisitionRequest('/api/place/search',{text});waiting.remove();showPlaceChoices(result.places||[],result.query);if(result.places?.length)addAcquireChatMessage('识别到地点“'+result.query+'”。对话中列出地图匹配结果，请选择正确地点；确认后会生成道路采样点。')}catch(error){waiting.textContent=error.message||'请输入一个具体地点，例如“南京市江宁区”或“长沙岳麓区大学城”。'}finally{$('#acquireChatForm button').disabled=false;input.focus()}});
$('#addStreetImages')?.addEventListener('click',async()=>{const selected=acquisition.items.filter(x=>x.selected);if(!selected.length)return;if(!await checkAcquisitionService()){toast('请先运行 acquisition_service/start_acquisition_service.command');return}acquisition.controller=new AbortController();$('#addStreetImages').disabled=true;$('#cancelStreetQuery').hidden=false;$('#cancelStreetQuery').disabled=false;let added=0,failed=0;try{for(let i=0;i<selected.length;i++){if(acquisition.controller.signal.aborted)break;const point=selected[i];setAcquireProgress(i,selected.length,'正在采集 '+(i+1)+' / '+selected.length+'：'+(point.road_name||point.point_id));try{const result=await acquisitionRequest('/api/collect',{latitude:point.latitude,longitude:point.longitude,heading:point.heading,point_id:point.point_id,road_id:point.road_id||''},acquisition.controller.signal),bytes=Uint8Array.from(atob(result.image_base64),char=>char.charCodeAt(0)),blob=new Blob([bytes],{type:result.image_type||'image/jpeg'}),file=new File([blob],'baidu_'+result.pano_id+'_'+(point.point_id||i+1)+'.jpg',{type:blob.type}),sourceMetadata={provider:'Baidu panorama',image_id:String(result.pano_id),image_url:'https://map.baidu.com/',captured_at:result.capture_date||null,longitude:result.pano_longitude,latitude:result.pano_latitude,requested_longitude:result.requested_longitude,requested_latitude:result.requested_latitude,compass_angle:result.heading,attribution:'Baidu panorama '+result.pano_id,license:'需用户确认已获来源授权',distance_to_sample_m:result.distance_to_sample_m,road_id:result.road_id,road_name:point.road_name||''};if(state.batchItems.some(item=>item.sourceMetadata?.provider==='Baidu panorama'&&item.sourceMetadata.image_id===String(result.pano_id)&&Math.abs(Number(item.sourceMetadata.compass_angle||0)-Number(result.heading||0))<2)){failed++;continue}state.batchItems.push({id:crypto.randomUUID?.()||Date.now()+'-'+Math.random(),file,url:URL.createObjectURL(file),status:'queued',predictions:[],sourceMetadata});added++;point.error='';renderBatch()}catch(error){if(error.name==='AbortError')throw error;failed++;point.error=error.message;toast((point.point_id||'采样点')+'：'+error.message)}renderAcquireResults()}setAcquireProgress(selected.length,selected.length,'采集结束 · '+added+' 张加入队列'+(failed?' · '+failed+' 个未成功':''));if(added)toast(added+' 张街景已加入批量任务')}catch(error){if(error.name==='AbortError')toast('采集已停止；已完成的图片保留在批量队列中');else toast('街景采集失败：'+error.message)}finally{acquisition.controller=null;$('#cancelStreetQuery').disabled=true;$('#cancelStreetQuery').hidden=['chat','road'].includes(selectedAcquireMode());renderAcquireResults()}});
$('#focusModel').addEventListener('click',()=>showPage(appMode==='project'?'page-batch':'page-workbench'));$$('.set-model').forEach(button=>button.addEventListener('click',()=>{$('#modelSelect').value=button.dataset.model;$('#modelSelect').dispatchEvent(new Event('change'));toast(appMode==='project'?'模型已选定，可在批量任务中运行':'模型已选定，返回单图检测即可运行')}));showPage(location.hash.slice(1)||'page-workbench',false);
window.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='u'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))input.click();if(e.key==='Enter'&&!['INPUT','SELECT','TEXTAREA','BUTTON'].includes(document.activeElement.tagName))$('#runDetection').click();if((e.key==='Delete'||e.key==='Backspace')&&state.selected!==null&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){rememberEdit();state.predictions.splice(state.selected,1);state.selected=null;drawBoxes();updateAnalytics()}});
$('#undoEdit').addEventListener('click',()=>{if(!state.undoStack.length)return;state.redoStack.push(clonePredictions());restoreEdit(state.undoStack.pop())});$('#redoEdit').addEventListener('click',()=>{if(!state.redoStack.length)return;state.undoStack.push(clonePredictions());restoreEdit(state.redoStack.pop())});$('#addBoxButton').addEventListener('click',()=>{if(!state.image){toast('请先上传街景图片');input.click();return}state.drawingMode=!state.drawingMode;state.showBoxes=true;$('#toggleBoxes').classList.add('selected');drawBoxes();state.zoom=1;$('#streetScene').style.transform='scale(1)';$('#sceneWrap').classList.toggle('drawing-mode',state.drawingMode);$('#addBoxButton').classList.toggle('selected',state.drawingMode);$('#addBoxButton').textContent=state.drawingMode?'完成补画':'＋ 补画漏检';toast(state.drawingMode?'在图像上拖动鼠标框出漏检目标':'已结束补画')});$('#sceneWrap').addEventListener('pointerdown',e=>{if(!state.drawingMode||e.button!==0||e.target.closest('.generated-box')||e.target.closest('.scene-tools')||e.target.closest('.scene-chip'))return;e.preventDefault();const rect=$('#sceneWrap').getBoundingClientRect(),sx=(e.clientX-rect.left)/rect.width*100,sy=(e.clientY-rect.top)/rect.height*100,draft=document.createElement('div');draft.className='box draft-box';$('#streetScene').appendChild(draft);const move=ev=>{const x=(ev.clientX-rect.left)/rect.width*100,y=(ev.clientY-rect.top)/rect.height*100;draft.style.left=Math.min(sx,x)+'%';draft.style.top=Math.min(sy,y)+'%';draft.style.width=Math.abs(x-sx)+'%';draft.style.height=Math.abs(y-sy)+'%'};const end=ev=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',end);const x=(ev.clientX-rect.left)/rect.width*100,y=(ev.clientY-rect.top)/rect.height*100;draft.remove();if(Math.abs(x-sx)<1.5||Math.abs(y-sy)<1.5)return;rememberEdit();const label=$('#newLabelCategory').value,box={xmin:Math.min(sx,x),ymin:Math.min(sy,y),xmax:Math.max(sx,x),ymax:Math.max(sy,y)};state.predictions.push({label,labelZh:names[label]||label,filterClass:Object.keys(accepted).find(k=>accepted[k].includes(label))||null,score:1,box,manual:true});state.selected=state.predictions.length-1;drawBoxes();updateAnalytics();setWorkflow(3)};window.addEventListener('pointermove',move);window.addEventListener('pointerup',end,{once:true})});
