// Guide navigation switches one chapter at a time without changing the page hash.
const guideToc=$('.guide-toc');
if(guideToc){
  const guideChapters=$$('.guide-chapter');
  const guideLinks=$$('.guide-toc a[href^="#guide-"]');
  const setGuideChapter=(id,scroll=false)=>{
    const chapter=guideChapters.find(item=>item.id===id);
    if(!chapter)return;
    guideChapters.forEach(item=>item.open=item===chapter);
    guideLinks.forEach(link=>{const active=link.hash===`#${id}`;link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current')});
    if(scroll)chapter.scrollIntoView({behavior:'smooth',block:'nearest'});
  };
  guideLinks.forEach(link=>link.addEventListener('click',event=>{event.preventDefault();setGuideChapter(link.hash.slice(1),true)}));
  guideChapters.forEach(chapter=>chapter.addEventListener('toggle',()=>{if(chapter.open){guideLinks.forEach(link=>{const active=link.hash===`#${chapter.id}`;link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','location');else link.removeAttribute('aria-current')})}}));
  $('#guideExpandAll')?.addEventListener('click',()=>{guideChapters.forEach(chapter=>chapter.open=true);$$('.guide-faq-list>details').forEach(item=>item.open=true)});
  $('#guideCollapseAll')?.addEventListener('click',()=>{guideChapters.forEach(chapter=>chapter.open=false);$$('.guide-faq-list>details').forEach(item=>item.open=false)});
}

// Fillable examples for location search; templates stay editable before submission.
const placeTemplateInput=$('#acquireChatInput');
$('#applyPlaceTemplate')?.addEventListener('click',()=>{
  const region=$('#chatTemplateRegion')?.value.trim()||'';
  const landmark=$('#chatTemplateLandmark')?.value.trim()||'';
  const location=[region,landmark].filter(Boolean).join(' ');
  if(!location){toast('请先填写城市/区县，或街道/地标');$('#chatTemplateRegion')?.focus();return}
  placeTemplateInput.value=landmark?`想采集${location}附近的街景`:region;
  placeTemplateInput.focus();
});
$$('.acquire-chat-example').forEach(button=>button.addEventListener('click',()=>{
  if(!placeTemplateInput)return;
  placeTemplateInput.value=button.dataset.query||'';
  placeTemplateInput.focus();
}));
